<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --brand-primary: oklch(52% 0.23 265);
  --brand-primary-hover: oklch(47% 0.22 265);
  --brand-primary-light: oklch(95% 0.02 265);
  --text-primary: oklch(15% 0.03 260);
  --text-secondary: oklch(58% 0.04 260);
  --text-tertiary: oklch(72% 0.02 260);
  --bg-page: oklch(98% 0.004 260);
  --bg-surface: oklch(100% 0 0);
  --bg-surface-hover: oklch(97% 0.01 260);
  --border-light: oklch(92% 0.01 260);
  --border-medium: oklch(86% 0.015 260);
  --green-positive: oklch(65% 0.17 160);
  --red-negative: oklch(55% 0.22 25);
  --green-bg: oklch(95% 0.03 160);
  --red-bg: oklch(95% 0.03 25);
  --yellow-warning: oklch(78% 0.15 85);
  --font-mono: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-lg: 0 4px 16px rgba(0,0,0,0.08);
}

html { font-size: 14px; }
body {
  font-family: var(--font-mono);
  background: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-width: 320px;
}

/* Feature flag for tabular numbers */
.tnum { font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }

/* Navigation */
.nav { background: var(--bg-surface); border-bottom: 1px solid var(--border-light); position: sticky; top: 0; z-index: 100; }
.nav-inner { max-width: 1400px; margin: 0 auto; padding: 0 20px; display: flex; align-items: center; height: 56px; gap: 24px; }
.nav-logo { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 1.15rem; color: var(--brand-primary); white-space: nowrap; text-decoration: none; }
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; gap: 4px; list-style: none; flex: 1; overflow-x: auto; scrollbar-width: none; }
.nav-links::-webkit-scrollbar { display: none; }
.nav-links a {
  text-decoration: none; color: var(--text-secondary); padding: 6px 12px; border-radius: var(--radius-sm);
  font-size: 0.9rem; font-weight: 500; white-space: nowrap; transition: color 0.15s, background 0.15s;
}
.nav-links a:hover, .nav-links a.active { color: var(--brand-primary); background: var(--brand-primary-light); }
.nav-cta { display: flex; gap: 8px; align-items: center; }
.nav-cta .btn-login { padding: 7px 16px; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.88rem; cursor: pointer; border: 1px solid var(--border-medium); background: var(--bg-surface); color: var(--text-primary); transition: all 0.15s; }
.nav-cta .btn-login:hover { background: var(--bg-surface-hover); }
.nav-cta .btn-signup { padding: 7px 16px; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.88rem; cursor: pointer; border: none; background: var(--brand-primary); color: #fff; transition: background 0.15s; }
.nav-cta .btn-signup:hover { background: var(--brand-primary-hover); }

/* Main container */
.main { max-width: 1400px; margin: 0 auto; padding: 0 20px; }

/* Top Bar Metrics */
.metrics-bar { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; padding: 16px 0; }
.metric-card { background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: var(--radius-md); padding: 14px 18px; display: flex; flex-direction: column; gap: 4px; }
.metric-label { font-size: 0.78rem; color: var(--text-secondary); font-weight: 500; text-transform: uppercase; letter-spacing: 0.04em; }
.metric-value { font-size: 1.35rem; font-weight: 700; font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }
.metric-change { font-size: 0.82rem; display: flex; align-items: center; gap: 4px; }
.metric-change.up { color: var(--green-positive); }
.metric-change.down { color: var(--red-negative); }
.metric-change.neutral { color: var(--text-secondary); }
.metric-extra { font-size: 0.78rem; color: var(--text-tertiary); }
.fear-greed-indicator { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 20px; font-weight: 600; font-size: 0.82rem; }
.fear-greed-indicator.neutral { background: oklch(93% 0.06 95); color: oklch(50% 0.12 85); }
.altcoin-badge { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 20px; font-weight: 600; font-size: 0.82rem; background: oklch(93% 0.04 265); color: var(--brand-primary); }

/* Promo Banner */
.promo-banner { background: linear-gradient(135deg, var(--brand-primary), oklch(45% 0.18 290)); border-radius: var(--radius-lg); padding: 14px 20px; margin-bottom: 12px; display: flex; align-items: center; justify-content: space-between; color: #fff; position: relative; overflow: hidden; cursor: pointer; }
.promo-banner::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse at 70% 50%, rgba(255,255,255,0.12), transparent 70%); }
.promo-content { position: relative; z-index: 1; display: flex; align-items: center; gap: 12px; }
.promo-icon { width: 36px; height: 36px; background: rgba(255,255,255,0.2); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; }
.promo-text { font-weight: 600; font-size: 0.95rem; }
.promo-cta { position: relative; z-index: 1; padding: 8px 18px; background: rgba(255,255,255,0.18); border: 1px solid rgba(255,255,255,0.3); border-radius: 20px; color: #fff; font-weight: 600; font-size: 0.85rem; cursor: pointer; transition: background 0.15s; white-space: nowrap; }
.promo-cta:hover { background: rgba(255,255,255,0.28); }
.promo-dots { display: flex; gap: 6px; position: relative; z-index: 1; }
.promo-dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,0.4); cursor: pointer; transition: all 0.2s; }
.promo-dot.active { background: #fff; width: 20px; border-radius: 10px; }
.promo-controls { display: flex; align-items: center; gap: 10px; position: relative; z-index: 1; }
.promo-arrow { width: 28px; height: 28px; border-radius: 50%; background: rgba(255,255,255,0.15); border: none; color: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; transition: background 0.15s; }
.promo-arrow:hover { background: rgba(255,255,255,0.3); }

/* AI Alerts Bar */
.ai-bar { background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: var(--radius-lg); padding: 12px 18px; margin-bottom: 12px; display: flex; align-items: center; gap: 14px; }
.ai-icon { width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg, oklch(70% 0.18 290), oklch(60% 0.2 265)); display: flex; align-items: center; justify-content: center; color: #fff; font-size: 0.9rem; flex-shrink: 0; }
.ai-prompt { font-size: 0.9rem; color: var(--text-primary); font-weight: 500; flex-shrink: 0; }
.ai-suggestions { display: flex; gap: 8px; flex-wrap: wrap; overflow-x: auto; scrollbar-width: none; }
.ai-suggestions::-webkit-scrollbar { display: none; }
.ai-chip { padding: 6px 14px; border-radius: 20px; background: var(--brand-primary-light); color: var(--brand-primary); font-size: 0.8rem; font-weight: 500; cursor: pointer; white-space: nowrap; border: 1px solid transparent; transition: all 0.15s; }
.ai-chip:hover { border-color: var(--brand-primary); background: oklch(92% 0.04 265); }

/* Filter Tabs Row */
.filters-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; flex-wrap: wrap; gap: 10px; }
.network-tabs { display: flex; gap: 4px; }
.network-tab { padding: 7px 16px; border-radius: 20px; border: 1px solid var(--border-medium); background: var(--bg-surface); color: var(--text-secondary); font-size: 0.84rem; font-weight: 500; cursor: pointer; transition: all 0.15s; white-space: nowrap; }
.network-tab:hover { background: var(--bg-surface-hover); border-color: var(--text-tertiary); }
.network-tab.active { background: var(--brand-primary); color: #fff; border-color: var(--brand-primary); }

/* Category Tabs */
.category-tabs { display: flex; gap: 6px; margin-bottom: 10px; overflow-x: auto; scrollbar-width: none; }
.category-tabs::-webkit-scrollbar { display: none; }
.cat-tab { padding: 8px 18px; border-radius: var(--radius-sm); border: none; background: transparent; color: var(--text-secondary); font-size: 0.88rem; font-weight: 500; cursor: pointer; transition: all 0.15s; white-space: nowrap; position: relative; }
.cat-tab:hover { color: var(--text-primary); }
.cat-tab.active { color: var(--text-primary); font-weight: 600; background: var(--bg-surface); box-shadow: var(--shadow-sm); }
.cat-tab.active::after { content: ''; position: absolute; bottom: -1px; left: 8px; right: 8px; height: 2px; background: var(--brand-primary); border-radius: 2px; }

/* Index Tracker */
.index-tracker { background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: var(--radius-md); padding: 12px 18px; margin-bottom: 10px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; }
.index-name { font-weight: 600; font-size: 0.88rem; color: var(--text-primary); }
.index-price { font-weight: 700; font-size: 1.1rem; font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }
.index-changes { display: flex; gap: 16px; }
.index-change { font-size: 0.84rem; font-weight: 600; font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }
.index-change.up { color: var(--green-positive); }
.index-change.down { color: var(--red-negative); }
.index-label { font-size: 0.72rem; color: var(--text-tertiary); }

/* Table Controls */
.table-controls { display: flex; align-items: center; justify-content: space-between; padding: 10px 0; gap: 10px; flex-wrap: wrap; }
.table-sorts { display: flex; gap: 4px; }
.sort-btn { padding: 7px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border-medium); background: var(--bg-surface); color: var(--text-secondary); font-size: 0.82rem; font-weight: 500; cursor: pointer; transition: all 0.15s; display: flex; align-items: center; gap: 4px; }
.sort-btn:hover { background: var(--bg-surface-hover); }
.sort-btn.active { background: var(--brand-primary); color: #fff; border-color: var(--brand-primary); }
.table-actions { display: flex; gap: 8px; }
.action-btn { padding: 7px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border-medium); background: var(--bg-surface); color: var(--text-secondary); font-size: 0.82rem; font-weight: 500; cursor: pointer; transition: all 0.15s; display: flex; align-items: center; gap: 5px; }
.action-btn:hover { background: var(--bg-surface-hover); }
.action-btn.active { background: var(--brand-primary); color: #fff; border-color: var(--brand-primary); }

/* Columns Dropdown */
.columns-dropdown { display: none; position: absolute; right: 0; top: 100%; margin-top: 4px; background: var(--bg-surface); border: 1px solid var(--border-medium); border-radius: var(--radius-md); box-shadow: var(--shadow-lg); padding: 10px 14px; z-index: 50; min-width: 200px; }
.columns-dropdown.visible { display: block; }
.columns-dropdown label { display: flex; align-items: center; gap: 8px; padding: 6px 0; font-size: 0.84rem; cursor: pointer; color: var(--text-primary); }
.columns-dropdown input[type="checkbox"] { accent-color: var(--brand-primary); }
.table-actions-wrapper { position: relative; display: flex; gap: 8px; }

/* Filter Panel */
.filter-panel { display: none; background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: var(--radius-md); padding: 18px; margin-bottom: 10px; gap: 16px; flex-wrap: wrap; align-items: flex-end; }
.filter-panel.visible { display: flex; }
.filter-group { display: flex; flex-direction: column; gap: 4px; }
.filter-group label { font-size: 0.75rem; color: var(--text-secondary); font-weight: 500; text-transform: uppercase; letter-spacing: 0.04em; }
.filter-group select, .filter-group input { padding: 7px 12px; border: 1px solid var(--border-medium); border-radius: var(--radius-sm); font-size: 0.84rem; font-family: inherit; background: var(--bg-surface); color: var(--text-primary); min-width: 140px; }
.filter-group select:focus, .filter-group input:focus { outline: none; border-color: var(--brand-primary); box-shadow: 0 0 0 3px oklch(52% 0.23 265 / 0.12); }
.filter-apply { padding: 8px 20px; background: var(--brand-primary); color: #fff; border: none; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.84rem; cursor: pointer; }
.filter-apply:hover { background: var(--brand-primary-hover); }
.filter-reset { padding: 8px 20px; background: transparent; color: var(--text-secondary); border: 1px solid var(--border-medium); border-radius: var(--radius-sm); font-weight: 500; font-size: 0.84rem; cursor: pointer; }

/* Crypto Table */
.table-wrapper { overflow-x: auto; background: var(--bg-surface); border-radius: var(--radius-md); border: 1px solid var(--border-light); box-shadow: var(--shadow-sm); }
.crypto-table { width: 100%; border-collapse: collapse; min-width: 1100px; font-size: 0.84rem; }
.crypto-table thead { position: sticky; top: 0; z-index: 5; }
.crypto-table th {
  padding: 11px 14px; text-align: right; font-weight: 600; font-size: 0.76rem; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.04em; background: oklch(97% 0.008 260); border-bottom: 2px solid var(--border-light);
  white-space: nowrap; cursor: pointer; user-select: none; transition: color 0.15s;
}
.crypto-table th:hover { color: var(--text-primary); }
.crypto-table th:first-child { text-align: center; }
.crypto-table th:nth-child(2) { text-align: left; }
.crypto-table th .sort-arrow { font-size: 0.6rem; margin-left: 2px; opacity: 0.4; }
.crypto-table th.sorted .sort-arrow { opacity: 1; color: var(--brand-primary); }
.crypto-table td {
  padding: 10px 14px; text-align: right; border-bottom: 1px solid var(--border-light);
  font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; font-weight: 500;
}
.crypto-table td:first-child { text-align: center; color: var(--text-tertiary); font-weight: 500; font-size: 0.82rem; }
.crypto-table td:nth-child(2) { text-align: left; }
.crypto-table tbody tr { transition: background 0.1s; }
.crypto-table tbody tr:hover { background: var(--bg-surface-hover); }
.crypto-table .coin-name { display: flex; align-items: center; gap: 10px; }
.crypto-table .coin-icon { width: 26px; height: 26px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.68rem; color: #fff; flex-shrink: 0; }
.crypto-table .coin-info { display: flex; flex-direction: column; }
.crypto-table .coin-symbol { font-weight: 600; color: var(--text-primary); font-size: 0.86rem; }
.crypto-table .coin-fullname { font-size: 0.76rem; color: var(--text-tertiary); }
.price-col { font-weight: 600; color: var(--text-primary); }
.change-up { color: var(--green-positive); font-weight: 600; }
.change-down { color: var(--red-negative); font-weight: 600; }
.sparkline-cell { padding: 6px 10px !important; }
.sparkline-svg { width: 90px; height: 34px; display: block; }

/* Pagination */
.pagination { display: flex; align-items: center; justify-content: center; padding: 16px 0; gap: 4px; flex-wrap: wrap; }
.page-btn { width: 36px; height: 36px; border-radius: var(--radius-sm); border: 1px solid var(--border-medium); background: var(--bg-surface); color: var(--text-secondary); font-size: 0.84rem; font-weight: 500; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.15s; font-family: inherit; }
.page-btn:hover { background: var(--bg-surface-hover); border-color: var(--text-tertiary); }
.page-btn.active { background: var(--brand-primary); color: #fff; border-color: var(--brand-primary); }
.page-btn:disabled { opacity: 0.35; cursor: default; }
.page-info { font-size: 0.82rem; color: var(--text-tertiary); padding: 0 12px; }

/* Market Summary */
.market-summary { background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: var(--radius-md); padding: 18px 22px; margin: 16px 0; }
.market-summary h2 { font-size: 1rem; font-weight: 700; margin-bottom: 10px; color: var(--text-primary); }
.market-summary p { font-size: 0.88rem; color: var(--text-secondary); line-height: 1.7; }
.market-summary strong { color: var(--text-primary); }
.read-more-btn { display: inline-flex; align-items: center; gap: 4px; margin-top: 10px; padding: 8px 16px; background: var(--brand-primary-light); color: var(--brand-primary); border: none; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.84rem; cursor: pointer; font-family: inherit; transition: background 0.15s; }
.read-more-btn:hover { background: oklch(92% 0.04 265); }
.read-more-btn .chevron { transition: transform 0.2s; display: inline-block; }
.read-more-btn.expanded .chevron { transform: rotate(180deg); }
.market-detail { display: none; margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--border-light); }
.market-detail.visible { display: block; }
.market-detail-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
.market-detail-item { padding: 10px 14px; background: var(--bg-page); border-radius: var(--radius-sm); }
.market-detail-item .md-label { font-size: 0.76rem; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.04em; }
.market-detail-item .md-value { font-size: 1rem; font-weight: 700; font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }

/* Info Section */
.info-section { padding: 32px 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.info-card { padding: 20px; }
.info-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 8px; color: var(--text-primary); }
.info-card p { font-size: 0.86rem; color: var(--text-secondary); line-height: 1.7; }

/* Footer */
.footer { background: var(--bg-surface); border-top: 1px solid var(--border-light); margin-top: 32px; padding: 40px 20px 24px; }
.footer-inner { max-width: 1400px; margin: 0 auto; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 32px; margin-bottom: 28px; }
.footer-col h4 { font-size: 0.8rem; font-weight: 700; color: var(--text-primary); margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer-col a { text-decoration: none; color: var(--text-secondary); font-size: 0.84rem; transition: color 0.15s; }
.footer-col a:hover { color: var(--brand-primary); }
.footer-bottom { padding-top: 20px; border-top: 1px solid var(--border-light); display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; font-size: 0.82rem; color: var(--text-tertiary); }

/* Responsive */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .metrics-bar { grid-template-columns: repeat(2, 1fr); }
  .promo-banner { flex-direction: column; gap: 10px; align-items: flex-start; }
  .ai-bar { flex-direction: column; align-items: flex-start; }
  .ai-suggestions { width: 100%; }
  .network-tabs { width: 100%; overflow-x: auto; }
  .index-tracker { flex-direction: column; align-items: flex-start; }
  .table-controls { flex-direction: column; align-items: stretch; }
  .table-sorts { overflow-x: auto; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .metrics-bar { grid-template-columns: 1fr; }
  .nav-cta .btn-login { display: none; }
  .footer-grid { grid-template-columns: 1fr; }
}
</style>
</head>
